#!/usr/bin/env python3
"""Create a GitHub check run with inline annotations from a JSON scan report.

The Checks API gives structured annotations and an explicit pass/fail
conclusion, which is more useful than ``::error`` workflow commands. The script
caps annotations at GitHub's per-request limit (50); the complete result set
remains available in the JSON report.

This script is intentionally CI-only: it calls ``gh api`` and therefore needs
network access and a token with ``checks: write`` permission.
"""

from __future__ import annotations

import argparse
import json
import os
import sys
from pathlib import Path
from typing import Any, Mapping, Sequence

from github_api import create_check_run, run_gh

# GitHub accepts at most 50 annotations in a single check-run request.
GITHUB_ANNOTATION_LIMIT = 50

SEVERITY_RANK = {
    "info": 0,
    "low": 1,
    "medium": 2,
    "high": 3,
    "critical": 4,
}

ANNOTATION_LEVEL = {
    "critical": "failure",
    "high": "failure",
    "medium": "warning",
    "low": "notice",
    "info": "notice",
}


def severity_rank(severity: str) -> int:
    """Returns the ordering rank for a scanner severity."""

    return SEVERITY_RANK.get(severity.strip().lower(), SEVERITY_RANK["info"])


def conclusion_for(findings: Sequence[Mapping[str, Any]], fail_on: str) -> str:
    """Returns ``failure`` when a finding meets the configured threshold."""

    if fail_on == "none":
        return "success"
    threshold = severity_rank(fail_on)
    if any(severity_rank(str(finding.get("severity", "info"))) >= threshold for finding in findings):
        return "failure"
    return "success"


def count_by_severity(findings: Sequence[Mapping[str, Any]]) -> dict[str, int]:
    """Counts findings by normalized severity."""

    counts = {severity: 0 for severity in SEVERITY_RANK}
    for finding in findings:
        severity = str(finding.get("severity", "info")).strip().lower()
        counts[severity if severity in counts else "info"] += 1
    return counts


def annotation_for(finding: Mapping[str, Any]) -> dict[str, Any]:
    """Converts one scanner finding into a Checks API annotation."""

    location = finding.get("location") or {}
    path = str(location.get("file", "")).replace("\\", "/")
    if not path:
        raise ValueError("finding is missing location.file")

    start_line = max(int(location.get("line") or 1), 1)
    end_line = max(int(location.get("end_line") or start_line), start_line)
    severity = str(finding.get("severity", "info")).strip().lower()
    rule_id = str(finding.get("rule_id", "soroban-scan"))
    title = str(finding.get("title", "Security finding"))
    evidence = str(finding.get("evidence", "")).strip()
    remediation = str(finding.get("remediation", "")).strip()

    message = f"{rule_id}: {title}"
    if evidence:
        message = f"{message} — {evidence}"

    annotation: dict[str, Any] = {
        "path": path,
        "start_line": start_line,
        "end_line": end_line,
        "annotation_level": ANNOTATION_LEVEL.get(severity, "notice"),
        "message": message,
        "title": f"{rule_id} ({severity})",
    }
    if remediation:
        annotation["raw_details"] = remediation
    return annotation


def summary_markdown(
    findings: Sequence[Mapping[str, Any]],
    *,
    fail_on: str,
    conclusion: str,
    annotation_count: int,
    omitted: int,
) -> str:
    """Builds the check-run summary shown in the GitHub UI."""

    counts = count_by_severity(findings)
    total = len(findings)
    lines = [
        "### Soroban Security Scan",
        "",
        f"- Findings: **{total}**",
        f"- Threshold: `{fail_on}`",
        f"- Conclusion: `{conclusion}`",
        "",
        "| Severity | Count |",
        "| -------- | ----- |",
    ]
    for severity in ("critical", "high", "medium", "low", "info"):
        lines.append(f"| {severity} | {counts[severity]} |")

    lines.append("")
    if annotation_count:
        lines.append(f"Annotated {annotation_count} finding(s) inline.")
    else:
        lines.append("No inline annotations were created.")
    if omitted:
        lines.append(
            f"{omitted} finding(s) were not annotated because GitHub limits a "
            f"single check-run request to {GITHUB_ANNOTATION_LIMIT} annotations; "
            "the JSON report contains every finding."
        )
    lines.append("")
    lines.append(
        "Generated by `soroban-scan`. The scanner is deterministic and never "
        "executes the code it analyzes."
    )
    return "\n".join(lines)


def build_payload(
    report: Mapping[str, Any],
    *,
    name: str,
    head_sha: str,
    fail_on: str = "high",
    details_url: str | None = None,
    max_annotations: int = GITHUB_ANNOTATION_LIMIT,
) -> dict[str, Any]:
    """Builds the Checks API request body from a scanner JSON report."""

    if not head_sha:
        raise ValueError("head_sha is required")
    if fail_on not in (*SEVERITY_RANK, "none"):
        raise ValueError(f"unknown failure threshold: {fail_on}")
    if not 1 <= max_annotations <= GITHUB_ANNOTATION_LIMIT:
        raise ValueError(
            f"max_annotations must be between 1 and {GITHUB_ANNOTATION_LIMIT}"
        )

    findings = report.get("findings")
    if not isinstance(findings, list):
        raise ValueError("report is missing a findings array")

    selected = findings[:max_annotations]
    annotations = [annotation_for(finding) for finding in selected]
    omitted = len(findings) - len(selected)
    conclusion = conclusion_for(findings, fail_on)
    counts = count_by_severity(findings)

    if findings:
        title = (
            f"{len(findings)} finding(s): "
            f"{counts['critical']} critical, {counts['high']} high, "
            f"{counts['medium']} medium, {counts['low']} low, "
            f"{counts['info']} info"
        )
    else:
        title = "No security findings"

    output: dict[str, Any] = {
        "title": title,
        "summary": summary_markdown(
            findings,
            fail_on=fail_on,
            conclusion=conclusion,
            annotation_count=len(annotations),
            omitted=omitted,
        ),
        "annotations": annotations,
    }
    payload: dict[str, Any] = {
        "name": name,
        "head_sha": head_sha,
        "status": "completed",
        "conclusion": conclusion,
        "output": output,
    }
    if details_url:
        payload["details_url"] = details_url
    return payload


def default_details_url(repo: str | None) -> str | None:
    """Builds the workflow-run URL for the check run's details link."""

    server = os.environ.get("GITHUB_SERVER_URL", "https://github.com")
    run_id = os.environ.get("GITHUB_RUN_ID")
    if not repo or not run_id:
        return None
    return f"{server}/{repo}/actions/runs/{run_id}"


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--report",
        type=Path,
        required=True,
        help="scanner JSON report (--format json)",
    )
    parser.add_argument(
        "--repo",
        default=os.environ.get("GITHUB_REPOSITORY"),
        help="repository in owner/name form (default: GITHUB_REPOSITORY)",
    )
    parser.add_argument(
        "--head-sha",
        default=os.environ.get("GITHUB_SHA"),
        help="commit SHA the check applies to (default: GITHUB_SHA)",
    )
    parser.add_argument(
        "--name",
        default="Soroban Security Scan",
        help="check-run name shown in the GitHub UI",
    )
    parser.add_argument(
        "--fail-on",
        choices=(*SEVERITY_RANK, "none"),
        default="high",
        help="severity that makes the check conclusion a failure (default: high)",
    )
    parser.add_argument(
        "--details-url",
        default=None,
        help="optional details link (default: the current workflow run)",
    )
    parser.add_argument(
        "--max-annotations",
        type=int,
        default=GITHUB_ANNOTATION_LIMIT,
        help=f"annotations to send (1-{GITHUB_ANNOTATION_LIMIT}; default: {GITHUB_ANNOTATION_LIMIT})",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="print the request body without creating a check run",
    )
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    if not args.repo:
        parser.error("--repo is required (or set GITHUB_REPOSITORY)")
    if not args.head_sha:
        parser.error("--head-sha is required (or set GITHUB_SHA)")

    try:
        report = json.loads(args.report.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        parser.error(f"cannot read {args.report}: {error}")

    try:
        payload = build_payload(
            report,
            name=args.name,
            head_sha=args.head_sha,
            fail_on=args.fail_on,
            details_url=args.details_url or default_details_url(args.repo),
            max_annotations=args.max_annotations,
        )
    except (TypeError, ValueError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 1

    if args.dry_run:
        print(json.dumps(payload, indent=2, sort_keys=True))
        return 0

    try:
        created = create_check_run(args.repo, payload, runner=run_gh)
    except Exception as error:  # noqa: BLE001 - report the API error to the workflow
        print(f"error: {error}", file=sys.stderr)
        return 1

    summary = {
        "check_run_id": created.get("id"),
        "html_url": created.get("html_url"),
        "conclusion": payload["conclusion"],
        "annotations": len(payload["output"]["annotations"]),
    }
    print(json.dumps(summary, sort_keys=True))
    return 0


if __name__ == "__main__":
    sys.exit(main())
